!! Golden comparison of the BL99 temperature solve (`ice_temperature_changes`)
!! against the real upstream `temperature_changes`: 60 columns per constant
!! set that converge (cold and melting surface, with and without snow, 1, 4
!! and 7 ice layers, both conductivity options, brine and fresh ice,
!! `sw_redist` on and off with columns inside its band, 1800 and 3600 s steps)
!! and, per set, the columns on which upstream aborts because the iteration
!! does not converge (the port must raise `ICE_ERR_TSFC_NOCONV` on exactly
!! those).  Outputs compared: `Tsf`, the layer temperatures and enthalpies,
!! the sensible, latent and outgoing longwave fluxes, `fsurfn`, the two
!! conductive fluxes, `einex_sfc_flux`, and the shortwave after `sw_redist`.
!!
!! The tables are 17-significant-digit literals produced by calling the real
!! upstream routine (the oracle driver of this PR, gfortran -O0, FMA
!! contraction off); the surface balance is the bulk one at the upstream
!! default emissivity 0.985.
!!
!! Tolerances.  The port performs the same operations in the same order as
!! upstream, so the differences are round-off (measured worst below); a
!! converged iteration with discrete switches is in principle sensitive to a
!! one-ulp change in a comparison, hence the looser GPU-build tolerance.
module test_cice_golden_bl99_solver
   use, intrinsic :: iso_fortran_env, only: int32
   use, intrinsic :: ieee_arithmetic, only: ieee_is_finite
   use testdrive, only: new_unittest, unittest_type, error_type, test_failed
   use rdb_constants, only: wp
   use rdb_ice_errors, only: ICE_ERR_TSFC_NOCONV
   use rdb_ice_params, only: ice_constants_t, ice_constants, ICE_CONSTANTS_ICEPACK, ICE_CONSTANTS_CESM
   use rdb_ice_thermo_shared, only: ICE_SFC_BULK
   use rdb_ice_bl99, only: ICE_NITERMAX, ICE_SW_FRAC, ICE_SW_DTEMP, ice_temperature_changes
   implicit none
   private

   public :: collect_cice_golden_bl99_solver_tests

   integer, parameter :: NROW = 60
   integer, parameter :: NNOCONV = 4
   real(wp), parameter :: EMISSIVITY = 0.985_wp
      !! Upstream default surface emissivity.
   real(wp), parameter :: TOL_SOLVER = 1.0e-12_wp
      !! Measured worst normalised difference: 1.6e-14 over the 120 table columns (gfortran) and 6.6e-14
      !! on the V100 build; over 40,000 random columns checked side by side with upstream the worst was
      !! 4.7e-14 in `Tsf`, 1.1e-13 in the fluxes and 3.6e-13 in `fcondtop` (a difference of conductive
      !! fluxes, so it amplifies round-off).  One tolerance for both builds, ~3x the population worst.

contains

   subroutine collect_cice_golden_bl99_solver_tests(testsuite)
      type(unittest_type), allocatable, intent(out) :: testsuite(:)
      testsuite = [ &
                  new_unittest("temperature_changes_icepack_set", test_icepack), &
                  new_unittest("temperature_changes_cesm_set", test_cesm), &
                  new_unittest("noconvergence_matches_upstream_abort", test_noconv) &
                  ]
   end subroutine collect_cice_golden_bl99_solver_tests

   pure function nd(g, e, s) result(d)
      !! Difference normalised by `max(|e|, s)`; NaN propagates.
      real(wp), intent(in) :: g, e, s
      real(wp) :: d
      d = abs(g - e)/max(abs(e), s)
   end function nd

   subroutine run_set(error, label, a, set, worst)
      type(error_type), allocatable, intent(inout) :: error
      character(len=*), intent(in) :: label
      real(wp), intent(in) :: a(83, NROW)
      integer, intent(in) :: set
      real(wp), intent(out) :: worst
      type(ice_constants_t) :: c
      integer :: i, k, nil, conduct
      integer(int32) :: ierr
      logical :: brine, swr
      real(wp) :: zS(7), zT(7), zq(7), Isw(7), zqs(1), zTs(1), Ssw(1), Tsf, d, diag(3)
      real(wp) :: fsens, flat, flwout, fsurf, fct, fcb, einex, fsw, fsi
      character(len=160) :: msg

      c = ice_constants(set)
      worst = 0.0_wp
      do i = 1, NROW
         nil = nint(a(1, i))
         brine = a(2, i) > 0.5_wp
         conduct = nint(a(3, i))
         swr = a(4, i) > 0.5_wp
         zS = a(20:26, i)
         zT = a(27:33, i)
         zTs(1) = a(34, i)
         Isw = a(35:41, i)
         zq = a(42:48, i)
         zqs(1) = a(49, i)
         Ssw(1) = a(16, i)
         Tsf = a(18, i)
         fsw = a(14, i)
         fsi = a(15, i)
         fsens = 0.0_wp; flat = 0.0_wp; flwout = 0.0_wp; fsurf = 0.0_wp; fct = 0.0_wp; fcb = 0.0_wp; einex = 1.0_wp
         ierr = 0_int32
         call ice_temperature_changes(nil, 1, a(7, i), a(8, i), a(9, i), a(10, i), a(11, i), a(12, i), a(13, i), &
                                      EMISSIVITY, ICE_SFC_BULK, 0.0_wp, 0.0_wp, c, conduct, brine, &
                                      swr, ICE_SW_FRAC, ICE_SW_DTEMP, ICE_NITERMAX, &
                                      a(5, i), a(6, i), zS, a(17, i), a(19, i), &
                                      fsw, fsi, Ssw, Isw, zq, zT, zqs, zTs, Tsf, &
                                      fsens, flat, flwout, fsurf, fct, fcb, einex, diag, ierr)
         if (ierr /= 0_int32) then
            write (msg, '(a,a,i0,a,i0)') label, ": column ", i, " error bits ", ierr
            call test_failed(error, trim(msg))
            return
         end if
         ! pack the outputs in table order and compare with explicit finiteness checks
         call cmp(Tsf, a(50, i), 1.0_wp)
         do k = 1, nil
            call cmp(zT(k), a(50 + k, i), 1.0_wp)
            call cmp(zq(k), a(58 + k, i), 1.0_wp)
            call cmp(Isw(k), a(76 + k, i), 1.0_wp)
         end do
         call cmp(zTs(1), a(58, i), 1.0_wp)
         call cmp(zqs(1), a(66, i), 1.0_wp)
         call cmp(fsens, a(67, i), 1.0_wp)
         call cmp(flat, a(68, i), 1.0_wp)
         call cmp(flwout, a(69, i), 1.0_wp)
         call cmp(fsurf, a(70, i), 1.0_wp)
         call cmp(fct, a(71, i), 1.0_wp)
         call cmp(fcb, a(72, i), 1.0_wp)
         call cmp(einex, a(73, i), 1.0_wp)
         call cmp(fsw, a(74, i), 1.0_wp)
         call cmp(fsi, a(75, i), 1.0_wp)
         call cmp(Ssw(1), a(76, i), 1.0_wp)
         if (allocated(error)) return
      end do
      call check_worst()

   contains

      subroutine cmp(g, e, s)
         real(wp), intent(in) :: g, e, s
         if (.not. ieee_is_finite(g)) then
            write (msg, '(a,a,i0,a)') label, ": column ", i, " non-finite output"
            if (.not. allocated(error)) call test_failed(error, trim(msg))
            return
         end if
         d = nd(g, e, s)
         if (.not. (d <= worst)) worst = d
      end subroutine cmp

      subroutine check_worst()
         if (.not. (worst <= TOL_SOLVER)) then
            write (msg, '(a,a,es10.3,a,es10.3)') label, ": worst normalised difference ", worst, " > tolerance ", TOL_SOLVER
            call test_failed(error, trim(msg))
         end if
      end subroutine check_worst

   end subroutine run_set

   subroutine test_icepack(error)
      type(error_type), allocatable, intent(out) :: error
      real(wp) :: a(83, NROW), worst
      call load_temp_icepack(a)
      call run_set(error, "temperature_changes (icepack set)", a, ICE_CONSTANTS_ICEPACK, worst)
   end subroutine test_icepack

   subroutine test_cesm(error)
      type(error_type), allocatable, intent(out) :: error
      real(wp) :: a(83, NROW), worst
      call load_temp_cesm(a)
      call run_set(error, "temperature_changes (cesm set)", a, ICE_CONSTANTS_CESM, worst)
   end subroutine test_cesm

   subroutine noconv_one(error, label, a, set)
      type(error_type), allocatable, intent(inout) :: error
      character(len=*), intent(in) :: label
      real(wp), intent(in) :: a(49, NNOCONV)
      integer, intent(in) :: set
      type(ice_constants_t) :: c
      integer :: i, nil
      integer(int32) :: ierr
      real(wp) :: zS(7), zT(7), zq(7), Isw(7), zqs(1), zTs(1), Ssw(1), Tsf, diag(3)
      real(wp) :: fsens, flat, flwout, fsurf, fct, fcb, einex, fsw, fsi
      character(len=160) :: msg

      c = ice_constants(set)
      do i = 1, NNOCONV
         nil = nint(a(1, i))
         zS = a(20:26, i); zT = a(27:33, i); zTs(1) = a(34, i); Isw = a(35:41, i)
         zq = a(42:48, i); zqs(1) = a(49, i); Ssw(1) = a(16, i); Tsf = a(18, i)
         fsw = a(14, i); fsi = a(15, i)
         fsens = 0.0_wp; flat = 0.0_wp; flwout = 0.0_wp; fsurf = 0.0_wp; fct = 0.0_wp; fcb = 0.0_wp; einex = 0.0_wp
         ierr = 0_int32
         call ice_temperature_changes(nil, 1, a(7, i), a(8, i), a(9, i), a(10, i), a(11, i), a(12, i), a(13, i), &
                                      EMISSIVITY, ICE_SFC_BULK, 0.0_wp, 0.0_wp, c, nint(a(3, i)), a(2, i) > 0.5_wp, &
                                      a(4, i) > 0.5_wp, ICE_SW_FRAC, ICE_SW_DTEMP, ICE_NITERMAX, &
                                      a(5, i), a(6, i), zS, a(17, i), a(19, i), &
                                      fsw, fsi, Ssw, Isw, zq, zT, zqs, zTs, Tsf, &
                                      fsens, flat, flwout, fsurf, fct, fcb, einex, diag, ierr)
         if (ierr /= ICE_ERR_TSFC_NOCONV) then
            write (msg, '(a,a,i0,a,i0,a)') label, ": column ", i, " error bits ", ierr, " (expected exactly NOCONV)"
            call test_failed(error, trim(msg))
            return
         end if
     if (.not. (ieee_is_finite(Tsf) .and. ieee_is_finite(zT(1)) .and. ieee_is_finite(fct) .and. nint(diag(1)) == ICE_NITERMAX)) then
            call test_failed(error, label//": no-convergence outputs not defined, or iteration count /= 100")
            return
         end if
      end do
   end subroutine noconv_one

   subroutine test_noconv(error)
      type(error_type), allocatable, intent(out) :: error
      real(wp) :: a(49, NNOCONV)
      call load_noconv_icepack(a)
      call noconv_one(error, "icepack set", a, ICE_CONSTANTS_ICEPACK)
      if (allocated(error)) return
      call load_noconv_cesm(a)
      call noconv_one(error, "cesm set", a, ICE_CONSTANTS_CESM)
   end subroutine test_noconv

